xpath.script:
(function(){
    'use strict';

    var API='https://mig-farm-ai-backend.vercel.app/api/chat';
    var STREAM_API='https://mig-farm-ai-backend.vercel.app/api/chat-stream';
    var UI_VERSION='34.0.0';
    var UI_VERSION_KEY='mig_ai_ui_version';
    var HISTORY_KEY='mig_ai_history_v33';
    var SESSION_KEY='mig_ai_session_id_v33';
    var STATE_KEY='mig_ai_conversation_state_v33';
    var BASKET_KEY='mig_ai_inquiry_basket_v33';
    var FEEDBACK_KEY='mig_ai_feedback_v33';
    var MAX_LOCAL_HISTORY_MESSAGES=32;
    var MAX_REQUEST_HISTORY_MESSAGES=22;
    var MAX_REQUEST_HISTORY_CHARS=20000;
    var MAX_HISTORY_MESSAGE_CHARS=4000;
    var ALLOW_AUTONOMOUS_ACTIONS=false;

    function init(){
        var launcher=document.getElementById('mig-ai-launcher');
        var panel=document.getElementById('mig-ai-panel');
        var closeBtn=document.getElementById('mig-ai-close');
        var clearBtn=document.getElementById('mig-ai-clear');
        var input=document.getElementById('mig-ai-input');
        var sendBtn=document.getElementById('mig-ai-send');
        var messages=document.getElementById('mig-ai-messages');
        var typing=document.getElementById('mig-ai-typing');
        var quick=document.getElementById('mig-ai-quick');
        var sectionTitle=document.getElementById('mig-ai-section-title');
        var attachBtn=document.getElementById('mig-ai-attach');
        var voiceBtn=document.getElementById('mig-ai-voice');
        var fileInput=document.getElementById('mig-ai-file');
        var imagePreview=document.getElementById('mig-ai-image-preview');
        var status=document.getElementById('mig-ai-status');
        var unread=document.getElementById('mig-ai-unread');
        var basketBtn=document.getElementById('mig-ai-basket');
        var basketCount=document.getElementById('mig-ai-basket-count');
        var drawer=document.getElementById('mig-ai-drawer');
        var drawerClose=document.getElementById('mig-ai-drawer-close');
        var drawerBody=document.getElementById('mig-ai-drawer-body');
        var drawerFooter=document.getElementById('mig-ai-drawer-footer');
        var humanBtn=document.getElementById('mig-ai-human');
        var pendingImages=[];
        var activeImages=[];
        var activeImageTurns=0;
        var pendingCaptureTarget='';
        var lastResultItems=[];
        var activeChatProduct=null;
        var comparisonSelection=[];

        if(!launcher||!panel||!closeBtn||!clearBtn||!input||!sendBtn||!messages||!typing||!attachBtn||!fileInput||!imagePreview||!status||!basketBtn||!basketCount||!drawer||!drawerClose||!drawerBody||!drawerFooter||!humanBtn) return;

        // v34 context-resilience rule:
        // A UI deployment must never erase the user's conversation merely because the
        // presentation-layer version changed. Conversation/session/state are semantic
        // continuity data and are cleared only by an explicit user reset or invalid data.
        try{
            if(localStorage.getItem(UI_VERSION_KEY)!==UI_VERSION){
                localStorage.setItem(UI_VERSION_KEY,UI_VERSION);
            }
        }catch(e){}

        function clean(v){return String(v||'').replace(/\s+/g,' ').trim()}
        function setStatus(mode,text){
            status.classList.remove('is-busy','is-offline');
            if(mode==='busy')status.classList.add('is-busy');
            if(mode==='offline')status.classList.add('is-offline');
            status.textContent=text||(mode==='busy'?'أفهم طلبك وأجهّز الرد':mode==='offline'?'الاتصال غير مستقر':'متصل • جاهز أساعدك');
        }
        function autoGrow(){
            input.style.height='auto';
            input.style.height=Math.min(112,Math.max(44,input.scrollHeight))+'px';
        }
        function setPanelOpen(open){
            panel.classList.toggle('is-open',!!open);
            panel.setAttribute('aria-hidden',open?'false':'true');
            launcher.setAttribute('aria-expanded',open?'true':'false');
            if(document.body)document.body.classList.toggle('mig-ai-chat-open',!!open&&window.innerWidth<=640);
            if(open){
                if(unread)unread.classList.remove('is-visible');
                setTimeout(function(){input.focus();scrollBottom()},120);
            }
        }
        function markUnread(){
            if(panel.classList.contains('is-open')||!unread)return;
            unread.textContent='1';unread.classList.add('is-visible');
        }
        function clearConnectionCards(){
            messages.querySelectorAll('.mig-ai-connection-card').forEach(function(el){el.remove()});
        }
        function addConnectionNotice(copy,retry){
            clearConnectionCards();
            var card=document.createElement('div');card.className='mig-ai-connection-card';card.setAttribute('role','status');
            var title=document.createElement('div');title.className='mig-ai-connection-title';title.textContent='⏳ لحظة ونكمّل معك';card.appendChild(title);
            var body=document.createElement('div');body.className='mig-ai-connection-copy';body.textContent=copy;card.appendChild(body);
            var actions=document.createElement('div');actions.className='mig-ai-connection-actions';
            var retryBtn=document.createElement('button');retryBtn.type='button';retryBtn.className='mig-ai-retry';retryBtn.textContent='إعادة المحاولة';
            retryBtn.addEventListener('click',function(){card.remove();if(typeof retry==='function')retry()});
            var whatsapp=document.createElement('a');whatsapp.className='mig-ai-whatsapp';whatsapp.href='https://wa.me/971581768215?text='+encodeURIComponent('مرحبًا MIG FARM، محتاج مساعدة من فريق المبيعات.');whatsapp.target='_blank';whatsapp.rel='noopener noreferrer';whatsapp.textContent='واتساب مباشر';
            actions.appendChild(retryBtn);actions.appendChild(whatsapp);card.appendChild(actions);
            messages.insertBefore(card,typing);scrollBottom();markUnread();
        }
        function setupVoice(){
            if(!voiceBtn)return;
            var SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;
            if(!SpeechRecognition){voiceBtn.style.display='none';return}
            var recognition=new SpeechRecognition();var listening=false;
            recognition.lang=locale()==='en'?'en-US':'ar-AE';recognition.interimResults=true;recognition.continuous=false;
            recognition.onstart=function(){listening=true;voiceBtn.classList.add('is-listening');voiceBtn.textContent='■';setStatus('busy','أسمعك... تكلّم بطريقتك')};
            recognition.onresult=function(event){
                var transcript='';for(var i=event.resultIndex;i<event.results.length;i++)transcript+=event.results[i][0].transcript;
                input.value=clean((input.value?input.value+' ':'')+transcript);autoGrow();
            };
            recognition.onerror=function(){setStatus('offline','تعذّر تشغيل الصوت • اكتب رسالتك')};
            recognition.onend=function(){listening=false;voiceBtn.classList.remove('is-listening');voiceBtn.textContent='🎙';if(navigator.onLine)setStatus('ready');input.focus();autoGrow()};
            voiceBtn.addEventListener('click',function(){try{if(listening)recognition.stop();else recognition.start()}catch(e){console.warn('MIG voice:',e)}});
        }
        function normalizeProductRef(p){
            if(!p||!p.name)return null;
            return {
                name:clean(p.name),sku:clean(p.sku||''),external_id:clean(p.external_id||p.product_dossier?.external_id||''),
                product_id:Number(p.product_id)||null,product_template_id:Number(p.product_template_id)||null,
                price:p.price==null?'':String(p.price),currency:clean(p.currency||'AED'),availability:clean(p.availability||''),url:clean(p.url||''),
                image:clean(p.image||''),truth:{current:Boolean(p.truth&&p.truth.current),source:clean(p.truth&&p.truth.source||'')}
            };
        }
        function sameProductRef(a,b){
            var x=normalizeProductRef(a),y=normalizeProductRef(b);if(!x||!y)return false;
            if(x.external_id&&y.external_id)return x.external_id===y.external_id;
            if(x.sku&&y.sku)return clean(x.sku).toLowerCase()===clean(y.sku).toLowerCase();
            return clean(x.name).toLowerCase()===clean(y.name).toLowerCase();
        }
        function isGenericProductDetailLabel(value){
            var t=clean(value).toLowerCase();
            return /تفاصيل المنتج|استخدامه|استخدامها|product details|details and use/.test(t);
        }
        function matchingResultForLabel(label){
            var t=clean(label).toLowerCase();
            var matches=lastResultItems.filter(function(p){return p&&p.name&&t.indexOf(clean(p.name).toLowerCase())>=0});
            return matches.length===1?matches[0]:null;
        }
        // v34 semantic-boundary rule:
        // The browser must never infer user intent, topic switches, reference targets,
        // or attachment relevance from user wording. The backend conversation_state
        // is authoritative for semantic context. UI code only transports explicit
        // selections/files and renders server decisions.
        function serverVisualContextActive(){
            var state=conversationState();
            var visual=state&&state.active_visual_context;
            return Boolean(visual&&visual.active===true);
        }
        function locale(){
            var lang=(document.documentElement.getAttribute('lang')||'').toLowerCase();
            return lang.indexOf('en')===0?'en':'ar';
        }
        function session(){
            var id=localStorage.getItem(SESSION_KEY);
            if(!id){
                id='mig-'+Date.now()+'-'+Math.random().toString(36).slice(2,10);
                localStorage.setItem(SESSION_KEY,id);
            }
            return id;
        }
        function history(){
            try{
                var raw=localStorage.getItem(HISTORY_KEY);
                var parsed=raw?JSON.parse(raw):[];
                if(!Array.isArray(parsed))return [];
                return parsed.filter(function(item){
                    return item&&(/^(user|assistant)$/).test(String(item.role||''))&&clean(item.content);
                }).slice(-MAX_LOCAL_HISTORY_MESSAGES);
            }catch(e){return []}
        }
        function saveHistory(items){
            try{localStorage.setItem(HISTORY_KEY,JSON.stringify((Array.isArray(items)?items:[]).slice(-MAX_LOCAL_HISTORY_MESSAGES)))}catch(e){}
        }
        function historyForRequest(items){
            var source=Array.isArray(items)?items:history();
            var selected=[],totalChars=0;
            for(var i=source.length-1;i>=0&&selected.length<MAX_REQUEST_HISTORY_MESSAGES;i--){
                var item=source[i];
                if(!item||!(/^(user|assistant)$/).test(String(item.role||'')))continue;
                var content=String(item.content||'').trim().slice(0,MAX_HISTORY_MESSAGE_CHARS);
                if(!content)continue;
                if(selected.length&&totalChars+content.length>MAX_REQUEST_HISTORY_CHARS)break;
                totalChars+=content.length;
                selected.push({role:String(item.role),content:content});
            }
            return selected.reverse();
        }
        function conversationState(){
            try{
                var raw=localStorage.getItem(STATE_KEY);
                var parsed=raw?JSON.parse(raw):{};
                return parsed&&typeof parsed==='object'&&!Array.isArray(parsed)?parsed:{};
            }catch(e){return {}}
        }
        function saveConversationState(value){
            try{
                if(value&&typeof value==='object') localStorage.setItem(STATE_KEY,JSON.stringify(value));
            }catch(e){}
        }
        var restoredProductContext=conversationState().active_product_context;
        if(restoredProductContext&&restoredProductContext.active&&restoredProductContext.product){
            activeChatProduct=normalizeProductRef(restoredProductContext.product);
        }
        function pushHistory(role,content){
            var items=history();
            items.push({role:role,content:String(content||'').slice(0,MAX_HISTORY_MESSAGE_CHARS)});
            saveHistory(items);
        }
        function resetConversation(){
            localStorage.removeItem(HISTORY_KEY);
            localStorage.removeItem(SESSION_KEY);
            localStorage.removeItem(STATE_KEY);
            activeImages=[];activeImageTurns=0;
            window.location.reload();
        }
        function safeImageUrl(value){
            var raw=clean(value);if(!raw)return '';
            try{
                var parsed=new URL(raw,window.location.origin);
                if(parsed.protocol!=='http:'&&parsed.protocol!=='https:')return '';
                return parsed.href;
            }catch(e){return ''}
        }
        function safeActionUrl(value){
            var raw=clean(value);if(!raw)return '';
            if(/^(tel:|mailto:)/i.test(raw))return raw;
            return safeImageUrl(raw);
        }
        function productKey(product){
            var p=normalizeProductRef(product);if(!p)return '';
            return p.external_id||p.sku||String(p.product_id||p.product_template_id||'')||p.name.toLowerCase();
        }
        function inquiryItems(){
            try{
                var raw=localStorage.getItem(BASKET_KEY);var parsed=raw?JSON.parse(raw):[];
                return Array.isArray(parsed)?parsed.filter(function(item){return item&&item.product&&item.product.name}).slice(0,20):[];
            }catch(e){return []}
        }
        function saveInquiryItems(items){
            var cleanItems=(Array.isArray(items)?items:[]).slice(0,20);
            try{localStorage.setItem(BASKET_KEY,JSON.stringify(cleanItems))}catch(e){}
            updateBasketCount();if(drawer.classList.contains('is-open'))renderInquiryDrawer();
        }
        function priceNumber(value){
            var raw=String(value==null?'':value).replace(/,/g,'').match(/-?\d+(?:\.\d+)?/);
            var number=raw?Number(raw[0]):NaN;return Number.isFinite(number)&&number>=0?number:null;
        }
        function money(value,currency){
            var number=priceNumber(value);if(number===null)return 'السعر غير ظاهر';
            return (clean(currency||'AED')+' '+number.toFixed(number%1?2:0));
        }
        function updateBasketCount(){
            var count=inquiryItems().reduce(function(total,item){return total+Math.max(1,Number(item.qty)||1)},0);
            basketCount.textContent=String(count);basketCount.classList.toggle('is-visible',count>0);
            basketBtn.setAttribute('aria-label','فتح طلباتي'+(count?'، '+count+' منتجات':''));
        }
        function addInquiryProduct(product){
            var ref=normalizeProductRef(product);if(!ref)return false;
            var items=inquiryItems(),key=productKey(ref),found=false;
            items.forEach(function(item){if(productKey(item.product)===key)found=true});
            if(!found)items.push({product:ref,qty:1});
            saveInquiryItems(items);return !found;
        }
        function basketSummary(includeConversation){
            var items=inquiryItems();var lines=['مرحبًا MIG FARM، أحتاج مساعدة من فريق المبيعات.'];
            if(items.length){
                lines.push('','المنتجات التي أستفسر عنها:');
                items.slice(0,8).forEach(function(item,index){
                    var p=item.product;lines.push((index+1)+'. '+p.name+' × '+Math.max(1,Number(item.qty)||1)+(p.sku?' — SKU: '+p.sku:'')+(priceNumber(p.price)!==null?' — '+money(p.price,p.currency):''));
                    if(p.url)lines.push('   '+p.url);
                });
                if(items.length>8)lines.push('وباقي القائمة موجود داخل «طلباتي» في الشات.');
            }
            if(includeConversation){
                var recent=history().slice(-4);if(recent.length){lines.push('','آخر تفاصيل المحادثة:');recent.forEach(function(item){lines.push((item.role==='user'?'العميل: ':'المساعد: ')+clean(item.content).slice(0,260))});}
            }
            lines.push('','هذا طلب استفسار وليس تأكيد شراء أو دفع.');return lines.join('\n');
        }
        function whatsappUrl(text){return 'https://wa.me/971581768215?text='+encodeURIComponent(text)}
        function renderInquiryDrawer(){
            var items=inquiryItems();drawerBody.innerHTML='';drawerFooter.innerHTML='';
            if(!items.length){
                var empty=document.createElement('div');empty.className='mig-ai-basket-empty';
                var icon=document.createElement('span');icon.textContent='🧺';empty.appendChild(icon);empty.appendChild(document.createTextNode('لسه ما ضفتش منتجات. اختار «أضف لطلباتي» من أي بطاقة منتج.'));drawerBody.appendChild(empty);return;
            }
            items.forEach(function(item,index){
                var p=item.product;var card=document.createElement('div');card.className='mig-ai-basket-item';
                var info=document.createElement('div');var name=document.createElement('div');name.className='mig-ai-basket-name';name.textContent=p.name;name.dir='auto';info.appendChild(name);
                var price=document.createElement('div');price.className='mig-ai-basket-price';price.textContent=money(p.price,p.currency);info.appendChild(price);card.appendChild(info);
                var controls=document.createElement('div');controls.className='mig-ai-basket-controls';
                var minus=document.createElement('button');minus.type='button';minus.textContent='−';minus.setAttribute('aria-label','تقليل الكمية');
                var qty=document.createElement('strong');qty.textContent=String(Math.max(1,Number(item.qty)||1));
                var plus=document.createElement('button');plus.type='button';plus.textContent='+';plus.setAttribute('aria-label','زيادة الكمية');
                minus.addEventListener('click',function(){var all=inquiryItems();all[index].qty=Math.max(1,(Number(all[index].qty)||1)-1);saveInquiryItems(all)});
                plus.addEventListener('click',function(){var all=inquiryItems();all[index].qty=Math.min(999,(Number(all[index].qty)||1)+1);saveInquiryItems(all)});
                controls.appendChild(minus);controls.appendChild(qty);controls.appendChild(plus);card.appendChild(controls);
                var remove=document.createElement('button');remove.type='button';remove.className='mig-ai-basket-remove';remove.textContent='إزالة من طلباتي';remove.addEventListener('click',function(){var all=inquiryItems();all.splice(index,1);saveInquiryItems(all)});card.appendChild(remove);drawerBody.appendChild(card);
            });
            var knownTotal=0,knownCount=0,currencies={};
            items.forEach(function(item){var n=priceNumber(item.product.price);if(n!==null){knownTotal+=n*Math.max(1,Number(item.qty)||1);knownCount+=1;currencies[clean(item.product.currency||'AED')]=true}});
            var total=document.createElement('div');total.className='mig-ai-basket-total';
            var totalLabel=document.createElement('span');totalLabel.textContent='الإجمالي الظاهر';var totalValue=document.createElement('span');totalValue.dir='ltr';var currencyList=Object.keys(currencies);totalValue.textContent=knownCount&&currencyList.length===1?(currencyList[0]+' '+knownTotal.toFixed(2)):'يؤكده الفريق';total.appendChild(totalLabel);total.appendChild(totalValue);drawerFooter.appendChild(total);
            var note=document.createElement('div');note.className='mig-ai-basket-note';note.textContent='القائمة للاستفسار وتجهيز الطلب فقط؛ لا تعتبر شراء أو حجزًا أو دفعًا.';drawerFooter.appendChild(note);
            var send=document.createElement('a');send.className='mig-ai-basket-send';send.href=whatsappUrl(basketSummary(false));send.target='_blank';send.rel='noopener noreferrer';send.textContent='إرسال الاستفسار على واتساب';drawerFooter.appendChild(send);
            var clear=document.createElement('button');clear.type='button';clear.className='mig-ai-basket-clear';clear.textContent='مسح القائمة';clear.addEventListener('click',function(){saveInquiryItems([])});drawerFooter.appendChild(clear);
        }
        function setDrawerOpen(open){
            drawer.classList.toggle('is-open',!!open);drawer.setAttribute('aria-hidden',open?'false':'true');
            if(open){renderInquiryDrawer();drawerClose.focus()}else input.focus();
        }
        function addGuidedSelector(){
            messages.querySelectorAll('.mig-ai-guide-card').forEach(function(el){el.remove()});
            if(quick)quick.style.display='none';if(sectionTitle)sectionTitle.style.display='none';
            var card=document.createElement('div');card.className='mig-ai-guide-card';var state={};var index=0;
            var steps=[
                {key:'category',title:'تدور على إيه؟',options:function(){return ['بذور','أسمدة ومغذيات','مبيدات وحماية','ري وأدوات']}},
                {key:'need',title:'حدد المحصول أو الاحتياج',options:function(){
                    if(state.category==='بذور')return ['طماطم','خيار','فلفل','محصول آخر'];
                    if(state.category==='أسمدة ومغذيات')return ['نمو خضري','تزهير وإثمار','نقص عناصر','مشكلة بالنبات'];
                    if(state.category==='مبيدات وحماية')return ['حشرات','فطريات','أعشاب','مشكلة غير واضحة'];
                    return ['تنقيط','تايمر تحكم','مضخة','أدوات زراعية'];
                }},
                {key:'cultivation',title:'نظام الزراعة عندك؟',options:function(){return ['أرض مكشوفة','بيت محمي','زراعة مائية','غير متأكد']}},
                {key:'emirate',title:'أنت في أي منطقة؟',options:function(){return ['الشارقة','العين','دبي','أبوظبي','إمارة أخرى']}},
                {key:'scale',title:'الحجم المطلوب تقريبًا؟',options:function(){return ['تجربة صغيرة','مزرعة','مشروع','غير محدد']}}
            ];
            function finish(){
                card.remove();var prompt='أحتاج ترشيحًا موجهًا بناءً على احتياجي الكامل. القسم: '+state.category+'، المحصول أو المشكلة: '+state.need+'، نظام الزراعة: '+state.cultivation+'، المنطقة: '+state.emirate+'، الحجم: '+state.scale+'. افهم المعلومات معًا واسألني فقط عن معلومة ضرورية ناقصة قبل الترشيح.';sendText(prompt);
            }
            function render(){
                card.innerHTML='';var step=steps[index];
                var kicker=document.createElement('div');kicker.className='mig-ai-card-kicker';kicker.textContent='اختيار موجّه • خطوة '+(index+1)+' من '+steps.length;card.appendChild(kicker);
                var title=document.createElement('div');title.className='mig-ai-card-title';title.textContent=step.title;card.appendChild(title);
                var progress=document.createElement('div');progress.className='mig-ai-guide-progress';var bar=document.createElement('span');bar.style.width=(((index+1)/steps.length)*100)+'%';progress.appendChild(bar);card.appendChild(progress);
                var options=document.createElement('div');options.className='mig-ai-guide-options';step.options().forEach(function(label){
                    var button=document.createElement('button');button.type='button';button.className='mig-ai-guide-option';button.textContent=label;
                    button.addEventListener('click',function(){state[step.key]=label;if(index===steps.length-1)finish();else{index+=1;render()}});options.appendChild(button);
                });card.appendChild(options);
                if(index>0){var back=document.createElement('button');back.type='button';back.className='mig-ai-guide-back';back.textContent='رجوع للخطوة السابقة';back.addEventListener('click',function(){index-=1;render()});card.appendChild(back)}
            }
            render();messages.insertBefore(card,typing);scrollBottom();
        }
        function addLocalComparison(first,second){
            var a=normalizeProductRef(first),b=normalizeProductRef(second);if(!a||!b)return;
            var card=document.createElement('div');card.className='mig-ai-compare-card';
            var kicker=document.createElement('div');kicker.className='mig-ai-card-kicker';kicker.textContent='مقارنة مباشرة من البيانات الظاهرة';card.appendChild(kicker);
            var title=document.createElement('div');title.className='mig-ai-card-title';title.textContent='مقارنة سريعة بين المنتجين';card.appendChild(title);
            var table=document.createElement('table');table.className='mig-ai-compare-table';var body=document.createElement('tbody');
            [['المنتج',a.name,b.name],['السعر',money(a.price,a.currency),money(b.price,b.currency)],['التوفر',a.availability||'غير ظاهر',b.availability||'غير ظاهر'],['SKU',a.sku||'غير ظاهر',b.sku||'غير ظاهر']].forEach(function(row){
                var tr=document.createElement('tr');row.forEach(function(value,i){var cell=document.createElement(i===0?'th':'td');cell.textContent=value;cell.dir=i===0?'rtl':'auto';tr.appendChild(cell)});body.appendChild(tr);
            });table.appendChild(body);card.appendChild(table);
