            var ask=document.createElement('button');ask.type='button';ask.className='mig-ai-card-primary';ask.textContent='اسأل الذكاء عن الفرق الأنسب لي';ask.addEventListener('click',function(){sendText('قارن المنتجين حسب استخدامي، ووضح الفرق المؤكد وما الذي تحتاج أن تسألني عنه قبل الترشيح.',{productRefs:[a,b]})});card.appendChild(ask);
            messages.insertBefore(card,typing);scrollBottom();
