            var head=document.createElement('div');head.className='mig-ai-scan-head';var icon=document.createElement('div');icon.className='mig-ai-scan-icon';icon.textContent='🔎';var copy=document.createElement('div');var title=document.createElement('div');title.className='mig-ai-card-title';title.textContent='أفحص الصورة بعناية';var sub=document.createElement('div');sub.className='mig-ai-card-copy';sub.textContent='أستخرج الظاهر أولًا ثم أربطه بسؤالك من غير تخمين.';copy.appendChild(title);copy.appendChild(sub);head.appendChild(icon);head.appendChild(copy);card.appendChild(head);
            var steps=document.createElement('div');steps.className='mig-ai-scan-steps';['قراءة العناصر الظاهرة','مطابقة المنتج أو المشكلة','تجهيز رد واضح وآمن'].forEach(function(label,i){var item=document.createElement('div');item.className='mig-ai-scan-step'+(i===0?' is-active':'');item.textContent=label;steps.appendChild(item)});card.appendChild(steps);messages.insertBefore(card,typing);scrollBottom();
