                var wrap=document.createElement('div');wrap.className='mig-ai-image-thumb';
                var img=document.createElement('img');img.src=item.image_url;img.alt='صورة مرفقة';wrap.appendChild(img);
                var remove=document.createElement('button');remove.type='button';remove.className='mig-ai-image-remove';remove.textContent='×';
                remove.addEventListener('click',function(){pendingImages.splice(index,1);renderPendingImages()});wrap.appendChild(remove);imagePreview.appendChild(wrap);
            });
            imagePreview.classList.toggle('has-images',pendingImages.length>0);
        }
        function simpleImageHash(value){
            var str=String(value||''),h1=2166136261>>>0;
            var step=Math.max(1,Math.floor(str.length/2048));
            for(var i=0;i<str.length;i+=step){h1^=str.charCodeAt(i);h1=Math.imul(h1,16777619)>>>0;}
            return h1.toString(36)+'-'+str.length.toString(36);
        }
        function imageToDataUrl(file,captureTarget){
            return new Promise(function(resolve,reject){
                var reader=new FileReader();
                reader.onerror=function(){reject(new Error('image_read_failed'))};
                reader.onload=function(){
                    var img=new Image();
                    img.onerror=function(){reject(new Error('image_decode_failed'))};
                    img.onload=function(){
                        var max=1280,scale=Math.min(1,max/Math.max(img.width,img.height));
                        var canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));
                        var ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,canvas.width,canvas.height);
                        var quality=0.84,data=canvas.toDataURL('image/jpeg',quality);
                        while(data.length>900000&&quality>0.58){quality-=0.07;data=canvas.toDataURL('image/jpeg',quality)}
                        if(data.length>900000&&Math.max(canvas.width,canvas.height)>1050){
                            var shrink=1050/Math.max(canvas.width,canvas.height),small=document.createElement('canvas');
                            small.width=Math.max(1,Math.round(canvas.width*shrink));small.height=Math.max(1,Math.round(canvas.height*shrink));
                            small.getContext('2d').drawImage(canvas,0,0,small.width,small.height);data=small.toDataURL('image/jpeg',0.68);
                        }
                        resolve({type:'input_image',image_url:data,detail:'high',client_image_id:'img-'+simpleImageHash(data),capture_target:clean(captureTarget||''),width:canvas.width,height:canvas.height});
                    };img.src=String(reader.result||'');
                };reader.readAsDataURL(file);
            });
        }
        async function addSelectedImages(files){
            var list=Array.prototype.slice.call(files||[]).slice(0,Math.max(0,4-pendingImages.length));
            var captureTarget=pendingCaptureTarget;pendingCaptureTarget='';
            for(var i=0;i<list.length;i++){
                if(!/^image\/(png|jpeg|webp)$/i.test(list[i].type||'')) continue;
                try{pendingImages.push(await imageToDataUrl(list[i],captureTarget))}catch(e){console.warn('MIG image:',e)}
            }
            renderPendingImages();fileInput.value='';input.focus();
        }
        function addUserImageMessage(images){
            if(!images||!images.length)return;
            var wrap=document.createElement('div');wrap.className='mig-ai-quick';wrap.style.direction='ltr';
            images.forEach(function(item){var im=document.createElement('img');im.src=item.image_url;im.alt='صورة المستخدم';im.style.cssText='width:74px;height:74px;object-fit:cover;border-radius:12px;border:1px solid #d7e4d9';wrap.appendChild(im)});
            messages.insertBefore(wrap,typing);scrollBottom();
        }
        function scrollBottom(){messages.scrollTop=messages.scrollHeight}
        function appendSafeInline(target,value){
            var text=String(value||'');
            var pattern=/(\+?\d(?:[\s().-]*\d){6,}|[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/gi;
            var last=0,match;
            while((match=pattern.exec(text))){
                if(match.index>last)target.appendChild(document.createTextNode(text.slice(last,match.index)));
                var raw=match[0];
                var isPhone=/^\+?\d(?:[\s().-]*\d){6,}$/.test(raw);
                var token=document.createElement(isPhone?'a':'span');
                token.className='mig-ai-inline-ltr';token.dir='ltr';token.textContent=raw;
                if(isPhone){token.href='tel:'+raw.replace(/(?!^)\+|[^\d+]/g,'');token.setAttribute('aria-label','اتصال على '+raw)}
                target.appendChild(token);last=pattern.lastIndex;
            }
            if(last<text.length)target.appendChild(document.createTextNode(text.slice(last)));
        }
        function renderAssistantText(bubble,text){
            var raw=String(text||'');var lines=raw.split(/\r?\n/);
            if(lines.length<2){appendSafeInline(bubble,raw);return}
            bubble.classList.add('is-structured');var list=null;
            lines.forEach(function(source){
                var line=String(source||'').trim();if(!line){list=null;return}
                var bullet=line.match(/^[•\-]\s*(.+)$/);
                if(bullet){
                    if(!list){list=document.createElement('ul');list.className='mig-ai-msg-list';bubble.appendChild(list)}
                    var li=document.createElement('li');appendSafeInline(li,bullet[1]);li.dir='auto';list.appendChild(li);return;
                }
                list=null;var el=document.createElement('div');
                var heading=/^(المهم بسرعة|الاستخدام والوصف|مقارنة موثقة وسريعة|المواصفات المؤكدة من بيانات المنتج|بيانات الجرعة المكتوبة صراحة في ملف المنتج|أول فحوص آمنة|أهم سؤال يفرق بين الاحتمالات):?$/.test(line);
                el.className=heading?'mig-ai-msg-heading':/^SKU\s*:/i.test(line)?'mig-ai-msg-line mig-ai-msg-code':'mig-ai-msg-line';
                appendSafeInline(el,line);el.dir=/^SKU\s*:/i.test(line)?'ltr':'auto';bubble.appendChild(el);
            });
        }
        function responseMeta(data,results){
            var items=Array.isArray(results)?results:[];
            if(items.some(function(item){return item&&item.truth&&item.truth.current}))return {sourceLabel:'بيانات منتجات مباشرة ومحدّثة'};
            if(data&&(data.vision||data.visual_evidence))return {sourceLabel:'تحليل الصورة مع سياق سؤالك'};
            if(data&&data.agricultural_diagnosis)return {sourceLabel:'إرشاد تشخيصي أولي — يحتاج تفاصيل كافية'};
            return {sourceLabel:'مساعد MIG FARM — يوضح غير المؤكد'};
        }
        function saveFeedback(value,text){
            try{
                var raw=localStorage.getItem(FEEDBACK_KEY),items=raw?JSON.parse(raw):[];if(!Array.isArray(items))items=[];
                items.push({value:value,at:new Date().toISOString(),message:clean(text).slice(0,320),session_id:session()});localStorage.setItem(FEEDBACK_KEY,JSON.stringify(items.slice(-30)));
            }catch(e){}
            try{window.dispatchEvent(new CustomEvent('mig-ai-feedback',{detail:{value:value,session_id:session(),ui_version:UI_VERSION}}))}catch(e){}
        }
        function addMessage(role,text,meta){
            var bubble=document.createElement('div');
            bubble.className='mig-ai-message '+role;
            if(role==='assistant')renderAssistantText(bubble,text);else bubble.textContent=text;
            if(role==='assistant'){
                var source=document.createElement('div');source.className='mig-ai-message-source';source.textContent=(meta&&meta.sourceLabel)||'مساعد MIG FARM';bubble.appendChild(source);
                var tools=document.createElement('div');tools.className='mig-ai-message-tools';
                var copy=document.createElement('button');copy.type='button';copy.className='mig-ai-msg-tool';copy.textContent='نسخ';copy.setAttribute('aria-label','نسخ الرد');
                copy.addEventListener('click',function(){
                    var done=function(){copy.textContent='تم النسخ';setTimeout(function(){copy.textContent='نسخ'},1300)};
                    if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(String(text||'')).then(done).catch(function(){});else{var area=document.createElement('textarea');area.value=String(text||'');area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();try{document.execCommand('copy');done()}catch(e){}area.remove();}
                });tools.appendChild(copy);
                [['مفيد','up','👍'],['غير مفيد','down','👎']].forEach(function(item){
                    var button=document.createElement('button');button.type='button';button.className='mig-ai-msg-tool';button.textContent=item[2];button.setAttribute('aria-label',item[0]);
                    button.addEventListener('click',function(){tools.querySelectorAll('.mig-ai-msg-tool').forEach(function(el){if(el!==copy)el.classList.remove('is-active')});button.classList.add('is-active');saveFeedback(item[1],text)});tools.appendChild(button);
                });bubble.appendChild(tools);
            }
            messages.insertBefore(bubble,typing);
            scrollBottom();
            if(role==='assistant')markUnread();
            return bubble;
        }
        function addActions(actions){
