        function addAutonomousAction(action){
            if(!ALLOW_AUTONOMOUS_ACTIONS||!action||!action.action_id)return;
            messages.querySelectorAll('.mig-ai-action-card').forEach(function(el){if(el.getAttribute('data-action-id')===String(action.action_id))el.remove()});
            var card=document.createElement('div');card.className='mig-ai-action-card';card.setAttribute('data-action-id',action.action_id);
            var title=document.createElement('div');title.className='mig-ai-action-card-title';title.textContent=action.title||'إجراء آمن';card.appendChild(title);
            if(action.summary){var summary=document.createElement('div');summary.className='mig-ai-action-card-summary';summary.textContent=action.summary;summary.dir='auto';card.appendChild(summary)}
            if(action.status!=='awaiting_confirmation'){
                var done=document.createElement('div');done.className='mig-ai-action-result';
                done.textContent=action.status==='executed'?('تم التنفيذ'+(action.result&&action.result.reference?' — '+action.result.reference:'')):action.status==='cancelled'?'تم إلغاء الإجراء بدون إرسال بيانات.':'لم يتم التنفيذ، ولم يتم تأكيد طلب أو دفع.';
                card.appendChild(done);messages.insertBefore(card,typing);scrollBottom();return;
            }
            var lineInputs=[];
            if(Array.isArray(action.lines)&&action.lines.length){
                var lines=document.createElement('div');lines.className='mig-ai-action-lines';
                action.lines.forEach(function(item){
                    var row=document.createElement('label');row.className='mig-ai-action-line';
                    var name=document.createElement('span');name.className='mig-ai-action-line-name';name.textContent=item.name+(item.sku?' — '+item.sku:'');name.dir='auto';
                    var qty=document.createElement('input');qty.type='number';qty.min='1';qty.max='999';qty.step='1';qty.value=Math.max(1,Number(item.quantity)||1);qty.setAttribute('aria-label','الكمية');
                    row.appendChild(name);row.appendChild(qty);lines.appendChild(row);lineInputs.push({key:item.key,field:qty});
                });card.appendChild(lines);
            }
            var fields=document.createElement('div');fields.className='mig-ai-action-fields';var inputs={};
            function addField(key,label,type,wide,required){
                var field=document.createElement('input');field.type=type||'text';field.placeholder=label+(required?' *':'');field.setAttribute('aria-label',label);field.autocomplete=key==='name'?'name':key==='phone'?'tel':key==='email'?'email':'off';if(wide)field.className='mig-ai-action-field-wide';if(required)field.required=true;inputs[key]=field;fields.appendChild(field);
            }
            var required=Array.isArray(action.required_fields)?action.required_fields:[];
            if(required.indexOf('name')>=0)addField('name','الاسم','text',true,true);
            if(required.indexOf('order_ref')>=0)addField('order_ref','رقم الطلب','text',true,true);
            if(required.indexOf('phone')>=0)addField('phone','رقم الهاتف','tel',false,true);
            if(action.kind!=='order_status')addField('email','البريد الإلكتروني (اختياري)','email',false,false);
            card.appendChild(fields);
            var consentLabel=document.createElement('label');consentLabel.className='mig-ai-action-consent';var consent=document.createElement('input');consent.type='checkbox';var consentText=document.createElement('span');consentText.textContent=action.consent_text||'أوافق على تنفيذ الإجراء الموضح.';consentLabel.appendChild(consent);consentLabel.appendChild(consentText);card.appendChild(consentLabel);
            var validation=document.createElement('div');validation.className='mig-ai-action-card-summary';validation.style.display='none';validation.style.color='#9a5b05';card.appendChild(validation);
            var buttons=document.createElement('div');buttons.className='mig-ai-action-buttons';
            var confirm=document.createElement('button');confirm.type='button';confirm.className='mig-ai-action-confirm';confirm.textContent='تأكيد التنفيذ';
            var cancel=document.createElement('button');cancel.type='button';cancel.className='mig-ai-action-cancel';cancel.textContent='إلغاء';
            confirm.addEventListener('click',function(){
                var customer={};Object.keys(inputs).forEach(function(key){customer[key]=clean(inputs[key].value)});
                var missing=required.some(function(key){return !clean(customer[key])});
                if(missing||!consent.checked){validation.textContent='كمّل البيانات المطلوبة وفعّل الموافقة قبل التنفيذ.';validation.style.display='block';return}
                confirm.disabled=true;cancel.disabled=true;
                sendText('تأكيد تنفيذ الإجراء',{actionRequest:{action_id:action.action_id,confirm:true,consent:true,customer:customer,lines:lineInputs.map(function(item){return {key:item.key,quantity:Math.max(1,Math.min(999,Number(item.field.value)||1))}})}});
            });
            cancel.addEventListener('click',function(){confirm.disabled=true;cancel.disabled=true;sendText('إلغاء الإجراء',{actionRequest:{action_id:action.action_id,cancel:true}})});
            buttons.appendChild(confirm);buttons.appendChild(cancel);card.appendChild(buttons);messages.insertBefore(card,typing);scrollBottom();
        }
        function clearDynamicQuickReplies(){
            var old=messages.querySelectorAll('.mig-ai-quick.mig-ai-dynamic');
            old.forEach(function(el){el.remove()});
        }
        function addQuickReplies(items){
            clearDynamicQuickReplies();
            if(!Array.isArray(items)||!items.length) return;
            var wrap=document.createElement('div');
            wrap.className='mig-ai-quick mig-ai-dynamic';
            items.slice(0,6).forEach(function(item){
                var label=clean(typeof item==='string'?item:(item&&item.label));
                if(!label) return;
                // Never show one ambiguous "product details" button for multiple products.
                if(isGenericProductDetailLabel(label)&&lastResultItems.length>1)return;
                var bound=(item&&typeof item==='object'&&item.product)?item.product:matchingResultForLabel(label);
                if(!bound&&isGenericProductDetailLabel(label)&&lastResultItems.length===1)bound=lastResultItems[0];
                var button=document.createElement('button');
                button.type='button';
                button.className='mig-ai-chip';
                button.textContent=label;
                button.addEventListener('click',function(){sendText((item&&item.message)||label,bound?{productRef:bound}:undefined)});
                wrap.appendChild(button);
            });
            if(wrap.children.length){messages.insertBefore(wrap,typing);scrollBottom()}
        }
        function addVisualGuidance(guidance){
            var old=messages.querySelectorAll('.mig-ai-visual-actions');old.forEach(function(el){el.remove()});
            if(!guidance||!Array.isArray(guidance.actions)||!guidance.actions.length)return;
            var wrap=document.createElement('div');wrap.className='mig-ai-visual-actions';
            guidance.actions.slice(0,3).forEach(function(action){
