                var button=document.createElement('button');button.type='button';button.className='mig-ai-visual-action';button.textContent=action.label;
                button.addEventListener('click',function(){
                    if(action.type==='camera'){pendingCaptureTarget=clean(action.target||'');if(!attachBtn.disabled)fileInput.click();return;}
                    if(action.type==='message'){sendText(action.message||action.label);return;}
                });
                wrap.appendChild(button);
            });
            if(wrap.children.length){messages.insertBefore(wrap,typing);scrollBottom()}
        }

        function normalizeResults(results){
            if(!Array.isArray(results)) return [];
            var seen={};
            var out=[];
            results.forEach(function(p){
                if(!p||!p.name) return;
                var key=clean(p.url||'') || (clean(p.name).toLowerCase()+'|'+clean(p.price||''));
                if(seen[key]) return;
                seen[key]=true;
                out.push(p);
            });
            return out;
        }
        function compactProductReply(results){
            var items=normalizeResults(results);
            if(!items.length) return '';
            var count=items.length;
            return locale()==='en'
                ?('I found '+count+' matching product'+(count===1?'':'s')+'. Here are the clearest options:')
                :('حصلت لك '+count+' '+(count===1?'منتج مناسب':'منتجات مناسبة')+' 👇');
        }
        function addProducts(results){
            if(!Array.isArray(results)||!results.length) return;
            var wrap=document.createElement('div');
            wrap.className='mig-ai-products';
            var cleanResults=normalizeResults(results);
            lastResultItems=cleanResults.slice();
            if(cleanResults.length===1)activeChatProduct=normalizeProductRef(cleanResults[0]);
            comparisonSelection=[];
            cleanResults.slice(0,4).forEach(function(p){
                if(!p||!p.name) return;
                var card=document.createElement('div');
                card.className='mig-ai-product';
                var head=document.createElement('div');head.className='mig-ai-product-head';
                var imageUrl=safeImageUrl(p.image||'');
                if(imageUrl){var image=document.createElement('img');image.className='mig-ai-product-image';image.src=imageUrl;image.alt=p.name;image.loading='lazy';head.appendChild(image)}
                else{var placeholder=document.createElement('div');placeholder.className='mig-ai-product-image-placeholder';placeholder.textContent='🌿';head.appendChild(placeholder)}
                var copy=document.createElement('div');copy.className='mig-ai-product-copy';
                var productUrl=safeImageUrl(p.url||'');
                var nameWrap=productUrl?document.createElement('a'):document.createElement('div');
                nameWrap.className='mig-ai-product-link';
                if(productUrl){nameWrap.href=productUrl;nameWrap.target='_self'}
                var name=document.createElement('div');
                name.className='mig-ai-product-name';
                name.textContent=p.name;name.title=p.name;name.dir='auto';
                nameWrap.appendChild(name);
                copy.appendChild(nameWrap);

                var meta=document.createElement('div');
                meta.className='mig-ai-product-meta';
                var price=document.createElement('span');
                price.className='mig-ai-product-price';
                price.dir='ltr';price.textContent=money(p.price,p.currency);
                var stock=document.createElement('span');
                stock.className='mig-ai-product-stock';
                stock.textContent=p.availability||'التوفر غير ظاهر';
                meta.appendChild(price);meta.appendChild(stock);copy.appendChild(meta);
                var badges=document.createElement('div');badges.className='mig-ai-product-badges';
                var truthBadge=document.createElement('span');truthBadge.className='mig-ai-product-badge'+(p.truth&&p.truth.current?'':' is-neutral');truthBadge.textContent=p.truth&&p.truth.current?'✓ بيانات مباشرة':'بيانات ظاهرة فقط';badges.appendChild(truthBadge);
                if(p.sku){var skuBadge=document.createElement('span');skuBadge.className='mig-ai-product-badge is-neutral';skuBadge.textContent='SKU '+p.sku;skuBadge.dir='ltr';badges.appendChild(skuBadge)}
                copy.appendChild(badges);head.appendChild(copy);card.appendChild(head);

                var actions=document.createElement('div');actions.className='mig-ai-product-actions';
                var details=document.createElement('button');details.type='button';details.className='mig-ai-product-detail-btn';details.textContent=locale()==='en'?'Details & use':'التفاصيل والاستخدام';
                details.addEventListener('click',function(event){event.preventDefault();event.stopPropagation();activeChatProduct=normalizeProductRef(p);sendText(locale()==='en'?'Product details and use':'تفاصيل المنتج واستخدامه',{productRef:p})});
                actions.appendChild(details);
                var request=document.createElement('button');request.type='button';request.className='mig-ai-product-request-btn';request.textContent='＋ أضف لطلباتي';
                request.addEventListener('click',function(event){event.preventDefault();event.stopPropagation();var added=addInquiryProduct(p);request.classList.add('is-added');request.textContent=added?'✓ اتضاف لطلباتي':'✓ موجود في طلباتي'});actions.appendChild(request);
                if(cleanResults.length>1){
                    var compare=document.createElement('button');compare.type='button';compare.className='mig-ai-product-compare-btn';compare.textContent=locale()==='en'?'Select to compare':'اختيار للمقارنة';
                    compare.addEventListener('click',function(event){
                        event.preventDefault();event.stopPropagation();
                        var ref=normalizeProductRef(p);if(!ref)return;
                        var existing=-1;for(var ci=0;ci<comparisonSelection.length;ci++){if(sameProductRef(comparisonSelection[ci],ref)){existing=ci;break}}
                        if(existing>=0){comparisonSelection.splice(existing,1);compare.classList.remove('is-selected');compare.textContent=locale()==='en'?'Select to compare':'اختيار للمقارنة';return;}
                        comparisonSelection.push(ref);compare.classList.add('is-selected');compare.textContent=locale()==='en'?'Selected':'تم الاختيار';
                        if(comparisonSelection.length===2){
                            var pair=comparisonSelection.slice(0,2);comparisonSelection=[];
                            wrap.querySelectorAll('.mig-ai-product-compare-btn').forEach(function(button){button.classList.remove('is-selected');button.textContent=locale()==='en'?'Select to compare':'اختيار للمقارنة'});
                            addLocalComparison(pair[0],pair[1]);
                        }
                    });
                    actions.appendChild(compare);
                }
                card.appendChild(actions);
                wrap.appendChild(card);
            });
            if(wrap.children.length){
                messages.insertBefore(wrap,typing);
                if(cleanResults.length>4){
                    var note=document.createElement('div');note.className='mig-ai-result-note';
                    note.textContent=locale()==='en'?('Showing 4 of '+cleanResults.length+' results'):('بعرض لك أفضل 4 من '+cleanResults.length+' نتائج');
                    messages.insertBefore(note,typing);
                }
                scrollBottom();
            }
        }
        function busy(on){
            input.disabled=on;
            sendBtn.disabled=on;
            attachBtn.disabled=on;
            if(voiceBtn)voiceBtn.disabled=on;
            typing.classList.toggle('is-visible',on);
            if(on)setStatus('busy','أفهم طلبك وأجهّز الرد');
            else if(navigator.onLine)setStatus('ready');
            scrollBottom();
        }
        async function readBackendResponse(response){
            var contentType=String(response.headers.get('content-type')||'').toLowerCase();
            if(contentType.indexOf('text/event-stream')===-1||!response.body||!response.body.getReader){
                try{return await response.json()}catch(e){return {error:'invalid_response'}}
            }
            var reader=response.body.getReader(),decoder=new TextDecoder('utf-8'),buffer='',result=null,streamError=null;
            function consume(block){
                if(!block)return;
                var eventName='message',dataLines=[];
                block.split(/\r?\n/).forEach(function(line){
                    if(line.indexOf('event:')===0)eventName=line.slice(6).trim();
                    if(line.indexOf('data:')===0)dataLines.push(line.slice(5).trim());
                });
                if(!dataLines.length)return;
                var value={};try{value=JSON.parse(dataLines.join('\n'))}catch(e){return;}
                if(eventName==='result')result=value;
                if(eventName==='error')streamError=value;
            }
            while(true){
                var chunk=await reader.read();
                if(chunk.done)break;
                buffer+=decoder.decode(chunk.value,{stream:true});
                var boundary;
                while((boundary=buffer.indexOf('\n\n'))!==-1){consume(buffer.slice(0,boundary));buffer=buffer.slice(boundary+2);}
            }
            consume(buffer);
            if(streamError)return Object.assign({__stream_error:true},streamError);
            return result||{error:'empty_stream_response'};
        }
        async function sendText(text,options){
            var opts=options||{};
            var scanCard=null;
            var message=clean(typeof text==='string'?text:input.value);
            var retrySilent=opts.retrySilent===true;
            var retryImages=Array.isArray(opts.retryImages)?opts.retryImages.slice(0,4):[];
            var selectedComparisonProducts=Array.isArray(opts.productRefs)?opts.productRefs.map(normalizeProductRef).filter(Boolean).slice(0,4):[];
            if(selectedComparisonProducts.length>=2)activeChatProduct=null;
            if(opts.productRef)activeChatProduct=normalizeProductRef(opts.productRef)||activeChatProduct;
            // Never clear or switch semantic product context from message keywords here.
            // The previous server-confirmed product context is sent as evidence only;
            // the backend decides whether the current message keeps, corrects, or replaces it.
            if((!message&&!pendingImages.length&&!retryImages.length)||sendBtn.disabled) return;
            var reusedActiveImages=false;
            var imagesToSend=retryImages.length?retryImages:pendingImages.slice(0,4);
            if(imagesToSend.length){
                activeImages=imagesToSend.slice(0,4);
                activeImageTurns=0;
            }else if(activeImages.length&&serverVisualContextActive()){
                // Reuse attachments only when the SERVER says the visual context is active.
                // No keyword/regex interpretation of the user's message is performed here.
                imagesToSend=activeImages.slice(0,4);
                reusedActiveImages=true;
                activeImageTurns+=1;
            }
            pendingImages=[];renderPendingImages();

            input.value='';autoGrow();
            if(quick) quick.style.display='none';
            if(sectionTitle)sectionTitle.style.display='none';
            if(!retrySilent&&message)addMessage('user',message);
            if(!retrySilent&&!reusedActiveImages)addUserImageMessage(imagesToSend);
            if(imagesToSend.length&&!reusedActiveImages)scanCard=addVisualScanProgress();

            var historyBefore=history();
            if(retrySilent&&historyBefore.length&&historyBefore[historyBefore.length-1].role==='user'&&clean(historyBefore[historyBefore.length-1].content)===clean(message||'[صورة مرفقة]'))historyBefore.pop();
            // Send a bounded recent-context window instead of an arbitrarily tiny history
            // or an unbounded transcript. Old turns remain locally available while the
            // server receives enough recent conversational evidence for reference resolution.
            var requestHistory=historyForRequest(historyBefore);
            var payload={
                message:message,
                session_id:session(),
                locale:locale(),
                page_url:window.location.href,
                page_title:document.title||'',
                product_context:productContext(),
                selected_product_context:activeChatProduct,
                selected_product_contexts:selectedComparisonProducts,
                history:requestHistory,
                conversation_state:conversationState(),
                autonomous_action_request:ALLOW_AUTONOMOUS_ACTIONS?(opts.actionRequest||null):null,
                images:imagesToSend,
                visual_context_reused:reusedActiveImages
            };

            if(!retrySilent)pushHistory('user',message||'[صورة مرفقة]');
            clearConnectionCards();
            busy(true);

            var requestFailed=false;
            var requestTimeout=null;
            var controller=window.AbortController?new AbortController():null;
            try{
                var requestOptions={
                    method:'POST',
                    headers:{'Content-Type':'application/json'},
                    body:JSON.stringify(payload)
                };
                if(controller){requestOptions.signal=controller.signal;requestTimeout=setTimeout(function(){controller.abort()},45000)}
                var response=await fetch(STREAM_API,requestOptions);
                if(response.status===404||response.status===405)response=await fetch(API,requestOptions);
                var data=await readBackendResponse(response);

                if(!response.ok||data.__stream_error) throw new Error(data.reply||data.error||'request_failed');

                var reply=clean(data.reply||'');
                // A successful transport response without an assistant reply is not a
                // conversational answer. Treat it as a recoverable backend failure instead
                // of fabricating a generic assistant message in the browser.
                if(!reply) throw new Error('empty_backend_reply');
                var resultItems=normalizeResults(data.results||[]);
                // Keep the answer itself: comparison/price/availability must not be
                // replaced by a generic "found N products" sentence.
                var visibleReply=reply;

                addMessage('assistant',visibleReply,responseMeta(data,resultItems));
                addAutonomousAction(data.autonomous_action||null);

                // Keep the full backend reply in hidden conversation history.
                // This preserves follow-ups such as "cheapest?", "second one?", etc.
                pushHistory('assistant',reply);

                if(data.conversation_state){
                    saveConversationState(data.conversation_state);
                    var serverProductContext=data.conversation_state.active_product_context;
                    activeChatProduct=serverProductContext&&serverProductContext.active&&serverProductContext.product?normalizeProductRef(serverProductContext.product):null;
                    if(!data.conversation_state.active_visual_context||data.conversation_state.active_visual_context.active===false){
                        // Server is authoritative: once it closes visual context, drop local images.
                        activeImages=[];activeImageTurns=0;
                    }
                }

                if(resultItems.length){
                    addProducts(resultItems);
                    // Product cards already link to products, so avoid a redundant
                    // "open first product" button when cards are visible.
                    var filteredActions=(data.suggested_actions||[]).filter(function(action){
                        return action && action.type!=='page';
                    });
                    addActions(filteredActions);
                }else{
                    addActions(data.suggested_actions||[]);
                }

                addVisualGuidance(data.visual_guidance||null);
                addQuickReplies(data.quick_replies||[]);
            }catch(error){
                requestFailed=true;
                var retryOptions=Object.assign({},opts,{retrySilent:true,retryImages:imagesToSend});
                addConnectionNotice(
                    navigator.onLine
                        ?'تعذّر وصول الرد حاليًا. طلبك محفوظ هنا؛ اضغط إعادة المحاولة من غير ما تكتبه مرة ثانية.'
                        :'الإنترنت غير متصل حاليًا. أول ما يرجع الاتصال اضغط إعادة المحاولة.',
                    function(){sendText(message,retryOptions)}
                );
                console.error('MIG FARM AI:',error);
            }finally{
                if(requestTimeout)clearTimeout(requestTimeout);
                removeVisualScanProgress(scanCard);
                busy(false);
                if(requestFailed)setStatus('offline',navigator.onLine?'تعذّر الاتصال • إعادة المحاولة متاحة':'بانتظار رجوع الإنترنت');
                input.focus();
            }
        }

        launcher.addEventListener('click',function(){
            setPanelOpen(!panel.classList.contains('is-open'));
        });
        closeBtn.addEventListener('click',function(){setPanelOpen(false)});
        clearBtn.addEventListener('click',resetConversation);
        basketBtn.addEventListener('click',function(){setDrawerOpen(!drawer.classList.contains('is-open'))});
        drawerClose.addEventListener('click',function(){setDrawerOpen(false)});
        humanBtn.addEventListener('click',function(){window.open(whatsappUrl(basketSummary(true)),'_blank','noopener,noreferrer')});
        attachBtn.addEventListener('click',function(){if(!attachBtn.disabled)fileInput.click()});
        fileInput.addEventListener('change',function(){addSelectedImages(fileInput.files)});
        sendBtn.addEventListener('click',function(){sendText()});
        input.addEventListener('input',autoGrow);
        input.addEventListener('keydown',function(event){
            if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();sendText()}
        });
        document.addEventListener('keydown',function(event){if(event.key==='Escape'&&drawer.classList.contains('is-open'))setDrawerOpen(false);else if(event.key==='Escape'&&panel.classList.contains('is-open'))setPanelOpen(false)});
        window.addEventListener('online',function(){setStatus('ready','رجع الاتصال • جاهز نكمّل')});
        window.addEventListener('offline',function(){setStatus('offline','بانتظار رجوع الإنترنت')});
        window.addEventListener('resize',function(){if(document.body)document.body.classList.toggle('mig-ai-chat-open',panel.classList.contains('is-open')&&window.innerWidth<=640)});
        if(quick){
            quick.addEventListener('click',function(event){
                var flowButton=event.target.closest('[data-flow]');
                if(flowButton){var flow=flowButton.getAttribute('data-flow');if(flow==='guided')addGuidedSelector();if(flow==='image'&&!attachBtn.disabled)fileInput.click();return;}
                var button=event.target.closest('[data-message]');if(button)sendText(button.getAttribute('data-message')||'');
            });
        }
        setupVoice();autoGrow();updateBasketCount();
        setStatus(navigator.onLine?'ready':'offline',navigator.onLine?'متصل • جاهز أساعدك':'بانتظار رجوع الإنترنت');
    }

    if(document.readyState==='loading'){
        document.addEventListener('DOMContentLoaded',init);
    }else{
        init();
    }
})();
